    >>> e = []; isin(e, [1, e, 3])
    True
    >>> isin(e, [1, [], 3])
    False
    """
def isin(elt: Any, seq: Any) -> object {
    for x in seq {
        if (elt is x) {
            return True;
        }
    }
    return False;
}

